import 'dart:convert'; // Pour la conversion base64
import 'dart:typed_data'; // Pour les données binaires
import 'package:flutter/material.dart';

class ImageViewer extends StatelessWidget {
  // Ta chaîne base64 de l'image
  final String base64String =
      "data:image/png;base64,";

  @override
  Widget build(BuildContext context) {
    // Supprimer le préfixe "data:image/png;base64," pour ne garder que la partie base64
    String base64Image = base64String.split(',').last;

    // Convertir la chaîne base64 en Uint8List (données binaires)
    Uint8List bytes = base64Decode(base64Image);

    return Scaffold(
      appBar: AppBar(
        title: Text('Image View'),
      ),
      body: Center(
        // Afficher l'image depuis les données binaires
        child: Image.memory(bytes),
      ),
    );
  }
}

void main() {
  runApp(MaterialApp(
    home: ImageViewer(),
  ));
}
